function livePropertyEdit(p,slider,value,finished){
 if(readOnly(p))return;
 return liveRequestEdit(p.id,slider,{operation:'parameter',id:p.id,value:nativeValue(value,parameterDimension(p))},finished);
}
function liveRequestEdit(key,slider,request,finished){
 if(!liveProperty){
  if(busy)return;
  liveProperty={id:key,gesture:crypto.randomUUID().replaceAll('-',''),slider,pending:null,finished:false,running:false};
  setBusy(true,slider);$('#inspector').classList.remove('busy');if(slider.closest('#tools-page'))$('#tools-page').classList.remove('busy');
 }
 const edit=liveProperty;if(edit.id!==key||edit.slider!==slider)return;
 edit.pending=request;edit.finished=finished;
 if(edit.running)return;
 const pump=async()=>{
  edit.running=true;
  try{
   while(edit.pending!==null){
    const next=edit.pending;edit.pending=null;
    const current=component()?.params.find(x=>x.id===edit.id);
    if(next.operation==='parameter'&&current?.value===next.value)continue;
    model=await api('/api/mutate',{...next,editGesture:edit.gesture,revision:model.revision});
    prepareMesh();metrics();draw();if(page==='tools')refreshToolGeometry();
   }
  }catch(error){edit.finished=true;edit.pending=null;toast(error.message);}
  finally{
   edit.running=false;
   if(edit.finished){liveProperty=null;setBusy(false);render();}
  }
 };
 return pump();
}
