function editedInputs(spec,prefix,all=false){
 if(!spec)return[];
 return spec.inputs.filter(e=>e.editable).map(e=>{
  const el=document.getElementById(`${prefix}-${e.name}-${e.index}`);let values;
  if(el.dataset.numericList==='true'){const text=el.value.trim();values=text?text.split(/[,\s]+/).map(x=>{const value=Number(x);if(!Number.isFinite(value))throw Error(`${e.label||e.name}: enter finite positions separated by commas or spaces.`);return value;}):[];}
  else if(el.dataset.choiceList==='true'){values=[...el.selectedOptions].map(o=>o.value);}
  else if(el.dataset.vector==='true'){
   values=[[...el.querySelectorAll('[data-coordinate]')].map(input=>{const value=Number(input.value);if(!input.value.trim()||!Number.isFinite(value))throw Error(`${e.name}: enter three finite coordinates.`);return value;})];
  }else if(el.dataset.scalar==='true'){
   if(e.type===3)values=[el.value];
   else {if(el.tagName==='SELECT'&&!el.value.trim())throw Error(`${e.name}: choose a replacement geometry set.`);const value=Number(el.value);if(!el.value.trim()||!Number.isFinite(value)||(e.type===1&&!Number.isInteger(value)))throw Error(`${e.name}: enter a valid ${e.type===1?'integer':'number'}.`);values=[value];}
  }else {try{values=JSON.parse(el.value);}catch{throw Error(`${e.name}: enter a valid JSON array.`);}if(!Array.isArray(values))throw Error(`${e.name}: wrap values in [brackets].`);}
  return{name:e.name,index:e.index,values,changed:JSON.stringify(values)!==JSON.stringify(e.values)};
 }).filter(e=>all||e.changed).map(({changed,...e})=>e);
}
