  const entries=job.result.inputs.map(saved=>{const input=schema.inputs.find(e=>e.name===saved.name&&e.index===saved.index&&e.type===saved.type);if(!input||!Array.isArray(saved.values)||saved.values.length!==1)throw Error('The saved inputs do not match this reference workflow.');return {input,values:saved.values};});
