function inputDraft(spec,prefix){const draft=(spec?.inputs||[]).flatMap(e=>{const el=document.getElementById(`${prefix}-${e.name}-${e.index}`);if(!el)return[];return[{name:e.name,index:e.index,value:el.dataset.vector==='true'?[...el.querySelectorAll('[data-coordinate]')].map(x=>x.value):el.dataset.choiceList==='true'?[...el.selectedOptions].map(x=>x.value):el.value}];});const source=prefix==='analysis'?document.getElementById('analysis-source-run'):null;if(source)draft.push({sourceRun:source.value});return draft;}
